describe("FE-1 new request DTOs", () => {
  it("SubmitAllotmentReq accepts Decimal-as-number fields (no string coercion required)", () => {
    const req: SubmitAllotmentReq = {
      client_id: "c-1", model_id: "m-1", multiplier: 2,
      expected_cash_in: "2026-08-01", mgmt_fee: 0.015, incentive_fee: 0.2,
    };
    expect(typeof req.multiplier).toBe("number");
    expect(typeof req.mgmt_fee).toBe("number");
  });

  it("SubmitAllotmentReq allows fee overrides to be omitted (add-allotment/redemption modes)", () => {
    const req: SubmitAllotmentReq = { client_id: "c-1", model_id: "m-1", multiplier: 1, expected_cash_in: null };
    expect(req.mgmt_fee).toBeUndefined();
    expect(req.incentive_fee).toBeUndefined();
  });

  it("SubmitRedemptionReq defaults emergent to being optional (caller may omit it)", () => {
    const req: SubmitRedemptionReq = { client_id: "c-1", model_id: "m-1", multiplier: 1, expected_cash_out: "2026-08-01" };
    expect(req.emergent).toBeUndefined();
  });

  it("SubmitRedemptionReq accepts an explicit emergent flag", () => {
    const req: SubmitRedemptionReq = { client_id: "c-1", model_id: "m-1", multiplier: 0, expected_cash_out: null, emergent: true };
    expect(req.emergent).toBe(true);
  });

  it("RedemptionDecisionReq's verdict is a closed 'approve'|'reject' union", () => {
    const approve: RedemptionDecisionReq = { verdict: "approve" };
    const reject: RedemptionDecisionReq = { verdict: "reject", reason: "bad docs" };
    expect(approve.verdict).toBe("approve");
    expect(reject.reason).toBe("bad docs");
  });
});
